package com.nthexperience.desktop;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.graphics.*;
import android.media.AudioManager;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.*;
import java.io.*;
import java.util.function.BooleanSupplier;

/** Real-device input and integration checks for the final XP menu/control polish. */
public final class XpTidySmoke extends Instrumentation {
    MainActivity home;View root;SystemTray tray;DesktopStore store;int checks;
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();AudioManager audio=getTargetContext().getSystemService(AudioManager.class);int previous=audio.getStreamVolume(AudioManager.STREAM_MUSIC);try{
        Context c=getTargetContext();store=new DesktopStore(c);store.prefs.edit().clear().putInt("startup_mode",2).putBoolean("reduce_motion",true).commit();XpTheme.defaults(store);c.getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();c.getSharedPreferences(InitializationState.PREFS,0).edit().putInt("flow_version",2).putInt("step",InitializationState.Step.DONE.ordinal()).commit();c.getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(c,MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();java.lang.reflect.Field field=MainActivity.class.getDeclaredField("tray");field.setAccessible(true);tray=(SystemTray)field.get(home);await(home::hasWindowFocus,"Desktop gains focus");
        View speaker=find(root,"Volume control");hold(speaker);settle();check(node("Open Volume Control")!=null,"Holding speaker opens XP notification menu");shot("tidy-volume-menu");clickNode("Open Volume Control");settle();check(find(root,"Media volume") instanceof XpWidgets.Vertical,"Volume popup uses XP vertical trackbar");
        SeekBar slider=(SeekBar)find(root,"Media volume");int max=audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC);check(max>1&&!audio.isVolumeFixed(),"Emulator media stream can be adjusted");drag(slider,.85f,.1f);settle();check(audio.getStreamVolume(AudioManager.STREAM_MUSIC)>=max-1,"Real upward drag increases media volume");drag(slider,.1f,.9f);settle();check(audio.getStreamVolume(AudioManager.STREAM_MUSIC)<=1,"Real downward drag decreases media volume");
        int target=Math.min(5,max-1);Bundle value=new Bundle();value.putFloat(AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,target);ui(()->check(slider.performAccessibilityAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),value),"Accessible slider action is supported"));check(audio.getStreamVolume(AudioManager.STREAM_MUSIC)==target,"Accessible volume action changes real stream");ui(()->slider.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_UP)));check(audio.getStreamVolume(AudioManager.STREAM_MUSIC)>target,"Keyboard Up changes real stream");int restore=audio.getStreamVolume(AudioManager.STREAM_MUSIC);tap(find(root,"Mute media"));check(audio.getStreamVolume(AudioManager.STREAM_MUSIC)==0,"Mute changes actual stream");ui(tray::dismiss);ui(()->tray.show("volume"));settle();tap(find(root,"Mute media"));check(audio.getStreamVolume(AudioManager.STREAM_MUSIC)==restore,"Reopened popup restores previous volume");shot("tidy-volume-popup");ui(home::onBackPressed);check(!tray.showing(),"Back dismisses tray popup");
        ui(tray::customize);settle();clickNode("Notification icon: Volume");clickNode("Cancel");check(store.prefs.getBoolean("tray_volume",true),"Cancel keeps existing notification choices");ui(tray::customize);settle();clickNode("Notification icon: Volume");shot("tidy-customize");clickNode("OK");check(!store.prefs.getBoolean("tray_volume",true),"OK saves notification choices");check(!find(root,"Volume control").isShown(),"Hidden volume icon leaves taskbar");check(Boolean.FALSE.equals(DesktopBackup.parse(DesktopBackup.snapshot(store).toString()).values.get("tray_volume")),"Notification choice is included in backup");ui(tray::customize);settle();clickNode("Notification icon: Volume");clickNode("OK");check(find(root,"Volume control").isShown(),"Customize restores hidden icon");
        hold(find(root,"Clock and calendar"));settle();check(node("Adjust Date/Time")!=null,"Clock has XP context menu");clickNode("Adjust Date/Time");settle();check(find(root,"Property tab: Date & Time")!=null,"Clock command opens actual XP date/time properties");
        ui(()->tray.show("brightness"));settle();SeekBar brightness=(SeekBar)find(root,"Brightness");Bundle level=new Bundle();level.putFloat(AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,48);ui(()->check(brightness.performAccessibilityAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),level),"Brightness slider accepts accessible action"));check(store.prefs.getInt("brightness_window",-1)==50,"XP-styled brightness still saves window level");ui(tray::dismiss);
        for(boolean landscape:new boolean[]{false,true}){
            ui(()->home.setRequestedOrientation(landscape?ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE:ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));await(()->landscape?root.getWidth()>root.getHeight():root.getHeight()>root.getWidth(),"Orientation settles");
            for(String page:new String[]{"network","battery","volume","brightness","controls"}){ui(()->tray.show(page));settle();View cover=find(root,"System tray flyout");View panel=((ViewGroup)cover).getChildAt(0);check(panel.getTop()>=0&&panel.getBottom()<=cover.getHeight()&&panel.getWidth()<=cover.getWidth(),page+" flyout stays in work area");shot("tidy-"+page+(landscape?"-land":"-port"));ui(tray::dismiss);}
            for(String id:new String[]{"@browser","@notes","@computer","@control","@clock","@backup","@photos",MediaLibrary.PLAYER,"@taskmanager","@recent","@recycle","@organize"}){ui(()->home.open(id));settle();DesktopWindow window=window(root,id);check(window!=null&&window.body.getWidth()>100&&window.body.getHeight()>60,"Working window: "+id);ui(window::closeWindow);}
        }
        ui(()->{home.open("@transfer");});settle();XpTransferWizard wizard=(XpTransferWizard)window(root,"@transfer").body;RadioButton newer=(RadioButton)findText(wizard,"This is the new device — import a backup");ui(newer::performClick);check(newer.isChecked(),"XP radio control still selects transfer direction");
        result.putString("result","PASS: "+checks+" XP tidy checks; native hold menus, real volume drag/keyboard/accessibility/mute restore, notification OK/Cancel and backup, clock routing, brightness, bounded flyouts and 12 existing programs in both orientations.");finish(Activity.RESULT_OK,result);
    }catch(Throwable error){android.util.Log.e("XpSmoke","XP tidy check failed",error);try{shot("tidy-failure");}catch(Exception ignored){}result.putString("result","FAIL: "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}finally{try{audio.setStreamVolume(AudioManager.STREAM_MUSIC,previous,0);}catch(Exception ignored){}}}
    void ui(Runnable action){runOnMainSync(action);}void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;if(checks%8==0){Bundle progress=new Bundle();progress.putString("progress",label);sendStatus(0,progress);}}void settle()throws Exception{waitForIdleSync();Thread.sleep(180);}void await(BooleanSupplier condition,String label)throws Exception{for(int i=0;i<100;i++){boolean[] ok={false};ui(()->ok[0]=condition.getAsBoolean());if(ok[0]){check(true,label);return;}Thread.sleep(100);}throw new AssertionError(label);}
    View find(View v,String description){if(description.equals(v.getContentDescription()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=find(((ViewGroup)v).getChildAt(i),description);if(found!=null)return found;}return null;}
    View findText(View v,String text){if(v instanceof TextView&&text.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=findText(((ViewGroup)v).getChildAt(i),text);if(found!=null)return found;}return null;}
    DesktopWindow window(View v,String id){if(v instanceof DesktopWindow&&id.equals(((DesktopWindow)v).toolId))return (DesktopWindow)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){DesktopWindow found=window(((ViewGroup)v).getChildAt(i),id);if(found!=null)return found;}return null;}
    AccessibilityNodeInfo node(String label){return node(getUiAutomation().getRootInActiveWindow(),label);}AccessibilityNodeInfo node(AccessibilityNodeInfo parent,String label){if(parent==null)return null;if(label.contentEquals(parent.getText()==null?"":parent.getText())||label.contentEquals(parent.getContentDescription()==null?"":parent.getContentDescription()))return parent;for(int i=0;i<parent.getChildCount();i++){AccessibilityNodeInfo found=node(parent.getChild(i),label);if(found!=null)return found;}return null;}
    void clickNode(String label)throws Exception{AccessibilityNodeInfo item=node(label);if(item==null||!item.performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new AssertionError("Cannot click "+label);settle();}
    void input(int action,float x,float y,long start){MotionEvent event=MotionEvent.obtain(start,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(event,true);event.recycle();}
    void tap(View v)throws Exception{int[] p=new int[2];ui(()->v.getLocationOnScreen(p));long start=SystemClock.uptimeMillis();input(MotionEvent.ACTION_DOWN,p[0]+v.getWidth()/2f,p[1]+v.getHeight()/2f,start);input(MotionEvent.ACTION_UP,p[0]+v.getWidth()/2f,p[1]+v.getHeight()/2f,start);settle();}
    void hold(View v)throws Exception{int[] p=new int[2];ui(()->v.getLocationOnScreen(p));long start=SystemClock.uptimeMillis();input(MotionEvent.ACTION_DOWN,p[0]+v.getWidth()/2f,p[1]+v.getHeight()/2f,start);Thread.sleep(750);input(MotionEvent.ACTION_UP,p[0]+v.getWidth()/2f,p[1]+v.getHeight()/2f,start);settle();}
    void drag(View v,float from,float to)throws Exception{int[] p=new int[2];ui(()->v.getLocationOnScreen(p));float x=p[0]+v.getWidth()/2f;long start=SystemClock.uptimeMillis();input(MotionEvent.ACTION_DOWN,x,p[1]+v.getHeight()*from,start);for(int i=1;i<=8;i++){input(MotionEvent.ACTION_MOVE,x,p[1]+v.getHeight()*(from+(to-from)*i/8),start);Thread.sleep(30);}input(MotionEvent.ACTION_UP,x,p[1]+v.getHeight()*to,start);}
    void shot(String name)throws Exception{Bitmap image=getUiAutomation().takeScreenshot();File dir=new File(getTargetContext().getFilesDir(),"xp-verification");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
}
